import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Campaign timeline","description":"","frontmatter":{},"headers":[],"relativePath":"feature/campaign-timeline/spec.md","filePath":"feature/campaign-timeline/spec.md"}'),o={name:"feature/campaign-timeline/spec.md"};function r(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="campaign-timeline" tabindex="-1">Campaign timeline <a class="header-anchor" href="#campaign-timeline" aria-label="Permalink to &quot;Campaign timeline&quot;">​</a></h1><h2 id="objective-stories" tabindex="-1">Objective / stories <a class="header-anchor" href="#objective-stories" aria-label="Permalink to &quot;Objective / stories&quot;">​</a></h2><p>Manager edits the Campaign plan on one page, schedules Task/subtask ranges, assigns members and creates subtasks quickly. Campaign rows show task name, status and assignee; there is no personal-role column. Personal involvement remains available as a filter. Client views and submits Campaign feedback in a fixed rail; Task comments remain in Task detail.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Existing permissions, workflow transitions, deployment/closure and package quantities remain authoritative. Task detail opens in a dialog as explicitly requested by the user, overriding the general no-long-modal preference for this Task interaction only.</li><li>No checkbox decoration. Truncated names open existing Task details. Preserve existing subtask controls/status permissions.</li><li>Planned start is independent of actual firstStartedAt. New Tasks/subtasks default to today in workspace timezone and due=start+2 calendar days. Supervisor defaults to creator; no new approval privileges.</li><li>Move/resize ranges by calendar days, including outside Campaign/parent dates. Require start before end only; do not move Campaign dates/milestones or publishing schedules. Auto-save atomically on release; date inputs are a keyboard/non-drag alternative.</li><li>Inline assignee picker highlights selected user. Compact subtask creator accepts name/assignee/calendar icon; Enter submits and focuses a fresh name field, preserving assignee, resetting dates to the default.</li><li>Search Task/subtask; filters: my involvement (assignee OR supervisor), assignee, supervisor, status, type, deliverable, schedule/overdue. Match subtask retains parent context. No Custom filters, Labels or Sprints.</li><li>Resize columns using pointer or keyboard; store presentation widths by user/workspace, not server data. Weekend tint and today line. Internal scrolling and skeleton loading.</li><li>Campaign metadata auto-save serialized with optimistic version. Errors preserve unsaved text, display retry and block deployment until resolved. Conflicts refetch and require review; never blindly replay stale full plans.</li></ul><h2 id="api-db" tabindex="-1">API / DB <a class="header-anchor" href="#api-db" aria-label="Permalink to &quot;API / DB&quot;">​</a></h2><p>Add optional plannedStartDate Instant to Mongo tasks and embedded subtasks; reuse dueDate. Add batched campaign timeline read and revision-checked schedule endpoint. Existing assignee API remains in use. New fields are additive; no legacy start-date backfill. Update init and seeder along with migration. No APPLY on shared/production DB in this task.</p><h2 id="ui-states-i18n-themes" tabindex="-1">UI states / i18n / themes <a class="header-anchor" href="#ui-states-i18n-themes" aria-label="Permalink to &quot;UI states / i18n / themes&quot;">​</a></h2><p>Use campaign.timeline.* keys in parallel vi/en campaign.json. Loading skeleton, empty filtered list, storage error/retry, saving/saved/error and read-only states. Existing semantic/BrandHub tokens for both themes. Accessible pointer/keyboard alternatives, reduced motion, responsive internal calendar overflow.</p><h2 id="errors-out-of-scope-done" tabindex="-1">Errors / out of scope / Done <a class="header-anchor" href="#errors-out-of-scope-done" aria-label="Permalink to &quot;Errors / out of scope / Done&quot;">​</a></h2><p>No mock fallback or unauthorized controls. Handle revision/version conflicts without losing edits. No publish, review sequence, new Task-milestone relation or unrelated working-tree changes. Done after Web CI, targeted backend and timeline behavior checks, migration/init/seeder parity verified.</p><h2 id="approved-layout-refinement-—-2026-11-07" tabindex="-1">Approved layout refinement — 2026-11-07 <a class="header-anchor" href="#approved-layout-refinement-—-2026-11-07" aria-label="Permalink to &quot;Approved layout refinement — 2026-11-07&quot;">​</a></h2><ul><li>Compact Campaign title/save header; metadata, editable dates and strategy move to right rail above deployment conditions and Client feedback. Timeline fills remaining viewport with internal scrolling. Persistent vertical separators distinguish adjustable pinned columns and calendar.</li><li>Add milestone directly on the Campaign bar: hover previews a translucent diamond and date, click focuses an inline name input; Enter saves, Escape or clicking outside cancels a new draft. Existing markers open inline edit; no separate add popup or toolbar add button. Only editable DRAFT Campaign roles may mutate; preserve version checks, max 100 milestones and failed drafts.</li><li>Keep keyboard equivalents (focus rail, arrows choose day, Enter opens name) and native date alternative. Unscheduled Task rows show a state label rather than repeated Set schedule buttons; preview/create a date range from their calendar lane. Old rows remain unchanged until explicit action.</li><li>Fit-to-view spans the visible calendar; day/week/month remain available. VI/EN keys remain parallel; semantic colors in light/dark; reduced motion; desktop independent scroll and mobile natural flow. No API/DB changes for this refinement.</li></ul><h2 id="timeline-simplification-—-approved-2026-11-07" tabindex="-1">Timeline simplification — approved 2026-11-07 <a class="header-anchor" href="#timeline-simplification-—-approved-2026-11-07" aria-label="Permalink to &quot;Timeline simplification — approved 2026-11-07&quot;">​</a></h2><ul><li>Default daily scale; minimum legible column/zoom sizes, no month/year header or weekend shading. Campaign dates replace timeline title in the toolbar; remove Campaign information card while retaining compact strategy editing on the right. Persistent start/end references and an always-visible horizontal scroll control.</li><li>Rename Campaign root row to Milestone and reduce row height. Existing task/subtask/approval behavior stays authoritative.</li><li>A click on an unscheduled task lane immediately saves start at the pointed day and end three calendar days later, without a date popup. Explicit dragging may still set a different duration; creating a new Task/subtask retains its established defaults unless this click action is used.</li><li>Compact subtask form: name and controls adjacent, no expanding gap caused by shared Input wrappers. Full Vietnamese assignee heading; status cannot wrap when resized.</li></ul><h2 id="approved-date-column-correction-sketch-—-2026-11-07" tabindex="-1">Approved date/column correction sketch — 2026-11-07 <a class="header-anchor" href="#approved-date-column-correction-sketch-—-2026-11-07" aria-label="Permalink to &quot;Approved date/column correction sketch — 2026-11-07&quot;">​</a></h2><ul><li>Missing Campaign end date must still show at least a continuous 14-day planning window, including observed dates; never persist an invented end date.</li><li>One horizontal control only, aligned to calendar with previous/next-day arrows. Hide the duplicate native horizontal bar while preserving vertical scrolling and horizontal trackpad/Shift-wheel input.</li><li>Compact defaults: assignee avatar column ~56px, status ~100px; minimum status width derives from real status label content rather than header. Header ellipsis/tooltip allowed; badge and avatar must not wrap or clip. Wider widths restore complete headings.</li></ul><h2 id="milestone-drag-—-2026-11-07" tabindex="-1">Milestone drag — 2026-11-07 <a class="header-anchor" href="#milestone-drag-—-2026-11-07" aria-label="Permalink to &quot;Milestone drag — 2026-11-07&quot;">​</a></h2><p>Manager can drag an existing milestone diamond to change its date, snapping to calendar days within existing Campaign bounds. Drop auto-saves using the existing content version. Click still opens edit; Escape/pointer cancellation discards the drag. Failed saves retain the proposed date for explicit retry. Client remains read-only. Keyboard Left/Right moves one day. Semantic theme colors preserved; vi/en move hint keys added in parallel.</p><h2 id="inclusive-deadline-display-—-2026-11-07" tabindex="-1">Inclusive deadline display — 2026-11-07 <a class="header-anchor" href="#inclusive-deadline-display-—-2026-11-07" aria-label="Permalink to &quot;Inclusive deadline display — 2026-11-07&quot;">​</a></h2><p>Task bars include the deadline calendar day (07→10 covers four cells through end of 10). Remove floating date labels and native date tooltip on Task drag and milestone drag; retain accessible date descriptions. UI correction only: existing stored deadline timestamps and APIs unchanged.</p><h2 id="compact-timeline-controls-—-2026-11-07" tabindex="-1">Compact timeline controls — 2026-11-07 <a class="header-anchor" href="#compact-timeline-controls-—-2026-11-07" aria-label="Permalink to &quot;Compact timeline controls — 2026-11-07&quot;">​</a></h2><p>Milestone creation uses the clicked timeline day and only shows name/confirm/cancel (no date picker). Existing milestone editor retains its date control. Toolbar has Today plus styled day/week/month menu; default week. Remove fit button and fit menu option. Shared Radix dropdown theme and keyboard behavior, parallel existing vi/en labels reused.</p><h3 id="scale-selection-highlight" tabindex="-1">Scale selection highlight <a class="header-anchor" href="#scale-selection-highlight" aria-label="Permalink to &quot;Scale selection highlight&quot;">​</a></h3><p>Scale menu selected item uses background/text highlight only, no radio dot. Accessible radio selected state retained.</p><h2 id="compact-multiple-filters-—-2026-11-07" tabindex="-1">Compact multiple filters — 2026-11-07 <a class="header-anchor" href="#compact-multiple-filters-—-2026-11-07" aria-label="Permalink to &quot;Compact multiple filters — 2026-11-07&quot;">​</a></h2><p>Remove applied filter chip row under toolbar. Support multiple assignees/supervisors; avatar buttons toggle independent assignee selections. OR within people/status/type selection, AND between filter categories; preserve parent/subtask filter behavior. Selected avatars/checkbox rows and filter count indicate active filters. Clear stays inline/in popover. No API/DB changes.</p><h2 id="remove-duplicate-bottom-information-—-2026-11-07" tabindex="-1">Remove duplicate bottom information — 2026-11-07 <a class="header-anchor" href="#remove-duplicate-bottom-information-—-2026-11-07" aria-label="Permalink to &quot;Remove duplicate bottom information — 2026-11-07&quot;">​</a></h2><p>Remove duplicate bottom Campaign start/end controls, duration/milestone legend and daily-scroll caption. Keep functional horizontal scrollbar aligned with calendar. Top date fields/ruler remain unchanged; no API/DB change.</p><h2 id="toolbar-order-—-2026-11-07" tabindex="-1">Toolbar order — 2026-11-07 <a class="header-anchor" href="#toolbar-order-—-2026-11-07" aria-label="Permalink to &quot;Toolbar order — 2026-11-07&quot;">​</a></h2><p>Place Campaign dates/Today/scale toolbar above search/people/filter toolbar. Keep filter toolbar directly above timeline ruler. Preserve responsive wrapping and functionality.</p><h2 id="view-controls-in-filter-row-—-2026-11-07" tabindex="-1">View controls in filter row — 2026-11-07 <a class="header-anchor" href="#view-controls-in-filter-row-—-2026-11-07" aria-label="Permalink to &quot;View controls in filter row — 2026-11-07&quot;">​</a></h2><p>Date row contains only Campaign start/end. Today and scale menu move to the right side of the filter row immediately above ruler; preserve wrapping on narrow screens.</p><h2 id="personal-work-dropdown-styling-—-2026-11-07" tabindex="-1">Personal-work dropdown styling — 2026-11-07 <a class="header-anchor" href="#personal-work-dropdown-styling-—-2026-11-07" aria-label="Permalink to &quot;Personal-work dropdown styling — 2026-11-07&quot;">​</a></h2><p>Replace native personal-work filter dropdown with themed radio menu, selected background/text highlight only (no dot). Preserve all/related/assignee/supervisor options and logic, vi/en labels and keyboard support.</p><h2 id="filter-checkbox-layout-—-2026-11-07" tabindex="-1">Filter checkbox layout — 2026-11-07 <a class="header-anchor" href="#filter-checkbox-layout-—-2026-11-07" aria-label="Permalink to &quot;Filter checkbox layout — 2026-11-07&quot;">​</a></h2><p>Filter checkbox labels stay adjacent to checkbox, using available panel width. Long names wrap naturally without pushing text to far edge. Fix assignee, supervisor, status and type choices locally, shared Input unchanged.</p><h2 id="deliverable-choices-and-filter-audit-—-2026-11-07" tabindex="-1">Deliverable choices and filter audit — 2026-11-07 <a class="header-anchor" href="#deliverable-choices-and-filter-audit-—-2026-11-07" aria-label="Permalink to &quot;Deliverable choices and filter audit — 2026-11-07&quot;">​</a></h2><p>Deliverable filter supports multiple checkbox selections (OR within deliverables, AND with other categories). No selection means all. Sidebar category labels wrap within column, no overflow. All selectors in timeline filter popover are inline choices: people/status/type/deliverable checkboxes, schedule mutually exclusive radio list; toolbar mine/zoom remain themed menus. Existing closure/version workflows untouched.</p><h2 id="compact-popup-width-—-2026-11-07" tabindex="-1">Compact popup width — 2026-11-07 <a class="header-anchor" href="#compact-popup-width-—-2026-11-07" aria-label="Permalink to &quot;Compact popup width — 2026-11-07&quot;">​</a></h2><p>Reduce filter popover width to440px desktop; allocate164px category column so Vietnamese field labels remain one line. Constrain popover to viewport width. Truncate only extreme long category labels with full title; option names keep usable right-pane space.</p><h2 id="optional-strategy-and-selected-package-navigation-—-2026-11-07" tabindex="-1">Optional strategy and selected-package navigation — 2026-11-07 <a class="header-anchor" href="#optional-strategy-and-selected-package-navigation-—-2026-11-07" aria-label="Permalink to &quot;Optional strategy and selected-package navigation — 2026-11-07&quot;">​</a></h2><p>Deployment strategy is optional. Readiness has four required conditions: package prepared/current, valid Campaign dates, exact package-generated Tasks, all Tasks with deadlines. Strategy editor remains available, never blocks deploy. A chosen Workspace package opens navigation for Manager/Client regardless negotiation approval/preparation status; no package retains package/chat gate, existing role access rules remain. Desktop/mobile consistent. No fake approval or DB backfill.</p>',43)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
